import { readFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);

export async function createBrowserBundle() {
  const modules = ['parser', 'renderer', 'examples', 'app'];
  const source = (await Promise.all(modules.map(async name => {
    const content = await readFile(new URL(`src/${name}.js`, root), 'utf8');
    return content.replace(/^import .+;\n/gm, '').replace(/^export /gm, '');
  }))).join('\n');
  // A classic script avoids the CORS restrictions on file:// module imports.
  // Waiting for the DOM also supports the inline version in the document head.
  return `// Generated by npm run build. Edit src/ files, then rebuild.\n(() => {\n'use strict';\nconst start = () => {\n${source}\n};\nif (document.readyState === 'loading') {\n  document.addEventListener('DOMContentLoaded', start, { once: true });\n} else {\n  start();\n}\n})();\n`;
}

export async function createStandalone(bundle) {
  const css = await readFile(new URL('styles.css', root), 'utf8');
  const icon = (await readFile(new URL('assets/favicon.svg', root))).toString('base64');
  const safeScript = bundle.replace(/<\/script/gi, '<\\/script');
  return (await readFile(new URL('index.html', root), 'utf8'))
    .replace('<link rel="stylesheet" href="./styles.css">', () => `<style>${css}</style>`)
    .replace('<script defer src="./app.bundle.js"></script>', () => `<script>${safeScript}</script>`)
    .replace('href="./assets/favicon.svg"', () => `href="data:image/svg+xml;base64,${icon}"`)
    .replace('href="./"', 'href="#"');
}
